# 5b. Live-sync best_accuracy.pth to /kaggle/working/out/ every 60 s.
# Trainer writes to saved_models/ru_finetune/best_accuracy.pth whenever
# validation accuracy improves. We copy it to the notebook's output dir
# so that even if the session dies mid-training, the last-best
# checkpoint is downloadable. /kaggle/working/ is persistent for the
# session; files here appear in the notebook's "Output" tab.
import threading, time, shutil
OUTPUT_DIR = pathlib.Path("/kaggle/working/out")
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
_sync_stop = threading.Event()

def _sync_checkpoints():
    src = pathlib.Path('/kaggle/working/EasyOCR/trainer/saved_models/ru_finetune/best_accuracy.pth')
    dst = OUTPUT_DIR / 'best_accuracy.pth'
    last_mtime = 0.0
    while not _sync_stop.is_set():
        if src.exists():
            m = src.stat().st_mtime
            if m != last_mtime:
                try:
                    shutil.copy2(src, dst)
                    print(f'[sync] {dst} updated ({dst.stat().st_size / 1e6:.1f} MB)')
                    last_mtime = m
                except OSError as e:
                    print(f'[sync] failed: {e}')
        _sync_stop.wait(60)

_sync_thread = threading.Thread(target=_sync_checkpoints, daemon=True)
_sync_thread.start()
print(f'Checkpoint sync thread running → {OUTPUT_DIR}')

# 6. Train (stream output line-by-line so the log is visible + flushed).
import subprocess, pathlib
_runner_lines = [
    'import os, sys, yaml',
    'import torch.backends.cudnn as cudnn',
    'sys.path.insert(0, os.getcwd())',
    'from train import train',
    'from utils import AttrDict',
    "with open(sys.argv[1], encoding='utf-8') as f:",
    '    opt = AttrDict(yaml.safe_load(f))',
    'opt.character = opt.number + opt.symbol + opt.lang_char',
    "os.makedirs(f'./saved_models/{opt.experiment_name}', exist_ok=True)",
    'cudnn.benchmark = True',
    'cudnn.deterministic = False',
    'train(opt, amp=False)',
]
_runner = pathlib.Path('/kaggle/working/EasyOCR/trainer/_runner.py')
_runner.write_text('\n'.join(_runner_lines) + '\n', encoding='utf-8')

proc = subprocess.Popen(
    ['python', '-u', str(_runner), str(cfg_path)],
    cwd='/kaggle/working/EasyOCR/trainer',
    stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
    text=True, bufsize=1,
)
for line in proc.stdout:
    print(line, end='')
rc = proc.wait()
_sync_stop.set()
print(f'Training finished with exit code {rc}')

# 7. Final checkpoint copy (in case the sync thread missed the last save)
import shutil, pathlib
best = pathlib.Path('/kaggle/working/EasyOCR/trainer/saved_models/ru_finetune/best_accuracy.pth')
if best.exists():
    dest = OUTPUT_DIR / 'best_accuracy.pth'
    shutil.copy2(best, dest)
    print('Fine-tuned weights saved to notebook output:', dest)
    print('Download via the Output panel on the right side of the notebook.')
    print('Next: place at resources/easyocr_models/cyrillic_g2.pth locally, then python build.py')
else:
    print('WARNING: no best_accuracy.pth found — check training log above.')

